public class Main {
    public static void main(String[] args) {
        int weightKg = 12;

        String zone = "local";
        int fee = switch (zone) {
            case "local" -> 5;
            case "regional" -> 8;
            case "remote" -> {
                if (weightKg > 10) {
                    yield 15 + 10;
                } else {
                    yield 15;
                }
            }
            default -> 0;
        };
        System.out.println(zone + ": $" + fee);

        zone = "remote";
        fee = switch (zone) {
            case "local" -> 5;
            case "regional" -> 8;
            case "remote" -> {
                if (weightKg > 10) {
                    yield 15 + 10;
                } else {
                    yield 15;
                }
            }
            default -> 0;
        };
        System.out.println(zone + ": $" + fee);
    }
}
